import {test,expect,type Page,type BrowserContext} from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";
import {readFileSync,writeFileSync,mkdirSync} from "node:fs";
import {randomUUID,createHash} from "node:crypto";
import {Client} from "pg";
import {browserFixtureDatabaseUrl} from "../helpers/browser-database";
const origin=process.env.E2E_BASE_URL??"http://127.0.0.1:3000";
const password=()=>process.env.SYNTHETIC_SEED_PASSWORD??readFileSync(process.env.SYNTHETIC_SEED_PASSWORD_FILE??"data/secrets/seed-password","utf8").trim();
const evidence=(name:string,data:unknown)=>{mkdirSync(".local/p2-work/browser-evidence",{recursive:true});writeFileSync(`.local/p2-work/browser-evidence/${name}.json`,JSON.stringify(data,null,2));};
const tags=["wcag2a","wcag2aa","wcag21a","wcag21aa","wcag22aa"];
const suffix=()=>String(Date.now()).slice(-8)+String(Math.floor(Math.random()*1000)).padStart(3,"0");
let doctorId="",unitId="";
test.beforeEach(async({context})=>{await context.setExtraHTTPHeaders({"x-real-ip":"synthetic-p2-browser-"+randomUUID()});});
async function login(page:Page,user="synthetic.anc"){await page.goto("/login");await page.getByLabel("ชื่อผู้ใช้",{exact:true}).fill(user);await page.getByLabel("รหัสผ่าน",{exact:true}).fill(password());await page.getByRole("button",{name:"เข้าสู่ระบบ",exact:true}).click();await expect(page).toHaveURL(/\/$/);}
async function post(context:BrowserContext,path:string,body:unknown,patient=false){const name=patient?"nipt_p2_signing_csrf":"nipt_csrf";const cookie=(await context.cookies()).find(c=>c.name===name)?.value??"";return context.request.post(path,{headers:{origin,"x-csrf-token":cookie},data:body});}
async function scan(page:Page,label:string){const r=await new AxeBuilder({page}).withTags(tags).analyze();evidence(label+"-axe",{violations:r.violations,incomplete:r.incomplete});await test.info().attach(label+"-axe",{body:JSON.stringify({violations:r.violations,incomplete:r.incomplete}),contentType:"application/json"});expect(r.violations).toEqual([]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);}
async function draw(page:Page){await page.locator("canvas").scrollIntoViewIfNeeded();const b=(await page.locator("canvas").boundingBox())!;await page.mouse.move(b.x+b.width*.15,b.y+b.height*.5);await page.mouse.down();await page.mouse.move(b.x+b.width*.4,b.y+b.height*.25,{steps:8});await page.mouse.move(b.x+b.width*.65,b.y+b.height*.65,{steps:8});await page.mouse.up();}
async function register(page:Page,lab=false){await page.goto("/cases");await page.getByRole("button",{name:lab?"ลงทะเบียนโดย Lab":"ลงทะเบียน ANC",exact:true}).click();const n=suffix(),ln="00990"+n,hn="00990"+n;await page.getByLabel("LN HIS จำลอง",{exact:false}).fill(ln);await page.getByLabel("HN จำลอง",{exact:false}).fill(hn);const unit=page.getByLabel("หน่วยงานลงทะเบียน",{exact:false});await unit.selectOption(unitId);await expect(unit).toHaveValue(unitId);if(lab){const source=page.getByLabel("แหล่งของตัวระบุ",{exact:false});await source.selectOption("TUBE_LABEL");await expect(source).toHaveValue("TUBE_LABEL");}await page.getByRole("button",{name:"ตรวจและลงทะเบียน",exact:true}).click();await expect(page).toHaveURL(/\/cases\/[a-f0-9-]+$/);await expect(page.getByRole("heading",{name:/เคสจำลอง LN/})).toBeVisible();return {id:page.url().split("/").at(-1)!,ln,hn};}
async function apiCase(page:Page,lab=false){const n=suffix(),ln="990"+n,hn="990"+n;const r=await post(page.context(),"/api/p2/register",{ln,hn,unitId,origin:lab?"LAB_DIRECT":"ANC",idempotencyKey:randomUUID(),...(lab?{identifierSource:"REQUEST_FORM"}:{})});expect(r.ok()).toBe(true);return (await r.json()).caseId as string;}
async function fillRequest(page:Page){await page.getByRole("button",{name:"เปิดแบบขอส่งตรวจ 5 หมวด"}).click();await page.getByLabel("ชื่อผู้รับบริการจำลอง",{exact:false}).fill("จำลอง: ผู้รับบริการ Browser ภาษาไทยชื่อยาวเพื่อทดสอบการแสดงผล");await page.getByLabel("วันเกิด",{exact:true}).fill("1995-01-01");await page.getByLabel("น้ำหนัก (กก.)",{exact:false}).fill("40.004");await page.getByLabel("ส่วนสูง (ซม.)",{exact:false}).fill("100");await expect(page.getByTestId("bmi")).toHaveText("40.00");await expect(page.getByRole("dialog")).toContainText("ค่าคำนวณ 40.004");await page.getByLabel("แพทย์ผู้สั่งตรวจ",{exact:false}).selectOption(doctorId);
 await page.getByRole("button",{name:/^2\. การตั้งครรภ์/}).click();await page.getByLabel("กำหนดคลอด EDD",{exact:false}).fill("2027-03-18");await page.getByLabel("วันที่เจาะเลือด S1",{exact:false}).fill("2026-10-01");await page.getByLabel("ที่มาวันเจาะ",{exact:false}).selectOption("ANC");await page.getByLabel("ประเภทครรภ์",{exact:false}).selectOption("Singleton");await page.getByLabel("Vanishing twin",{exact:false}).selectOption("No");
 await page.getByRole("button",{name:/^3\. ประวัติทางการแพทย์/}).click();for(const select of await page.getByRole("dialog").locator("select").all())await select.selectOption("No");await page.getByRole("button",{name:/^4\. ความประสงค์/}).click();await page.getByLabel("ความประสงค์ทราบเพศทารก",{exact:false}).selectOption("DoNotWant");await page.getByLabel("ความประสงค์เรื่อง SCA",{exact:false}).selectOption("DoNotWant");await page.getByRole("button",{name:/^5\. ข้อควรทราบ/}).click();await page.getByRole("button",{name:"บันทึกร่าง / ลองใหม่"}).click();await expect(page.locator(".save-status")).toContainText("บันทึกแล้ว");}
async function modes(page:Page,requestMode:string,consentMode:string){await page.getByRole("button",{name:"เปลี่ยนช่องทาง Request / Consent"}).click();await page.getByLabel("ช่องทาง Request",{exact:true}).selectOption(requestMode);await page.getByLabel("ช่องทาง Consent",{exact:true}).selectOption(consentMode);await page.getByLabel("เหตุผลเปลี่ยนช่องทางจำลอง",{exact:false}).fill("จำลอง: เปลี่ยนช่องทางทดสอบ");await page.getByRole("button",{name:"บันทึกช่องทาง",exact:true}).click();await expect(page.getByRole("dialog")).toHaveCount(0);}
async function prepareAndStart(page:Page,ready=true){await page.getByRole("button",{name:"จัดเตรียม Consent / ส่งอุปกรณ์ลงนาม"}).click();await page.getByLabel("แพทย์และลายเซ็นรุ่นที่ได้รับอนุญาต",{exact:false}).selectOption(doctorId);await page.getByLabel("เหตุผลจัดเตรียมจำลอง",{exact:false}).fill("จำลอง: จัดเตรียม consent browser");await page.getByRole("button",{name:"จัดเตรียม Consent ฉบับใหม่",exact:true}).click();await expect(page.getByRole("dialog")).toHaveCount(0);await page.getByRole("button",{name:"จัดเตรียม Consent / ส่งอุปกรณ์ลงนาม"}).click();await page.getByLabel("ผู้รับบริการสมมติอยู่พร้อม",{exact:false}).check();await page.getByRole("button",{name:"เริ่มโหมดผู้รับบริการสมมติ",exact:true}).click();await expect(page).toHaveURL(/\/p2\/signing$/);if(ready)await expect(page.getByRole("heading",{name:"อ่านและรับทราบด้วยตนเองครบ 12 ข้อ"})).toBeVisible();}
async function acknowledgments(page:Page){for(let i=1;i<=12;i++){await page.getByLabel(`เข้าใจแล้ว ข้อ ${i}`,{exact:true}).check();await expect(page.getByLabel(`เข้าใจแล้ว ข้อ ${i}`,{exact:true})).toBeDisabled();}await expect(page.getByRole("status").filter({hasText:"รับทราบแล้ว"})).toContainText("12/12");}
async function returnStaff(page:Page,completed=true){await page.getByLabel("รหัสผ่านผู้จัดเตรียม",{exact:false}).fill(password());await page.getByRole("checkbox").check();await page.getByRole("button",{name:"ยืนยันตัวตนและกลับสิทธิ์เจ้าหน้าที่",exact:true}).click();await expect(page.getByRole("heading",{name:"ยืนยันตัวตนผู้จัดเตรียมแล้ว"})).toBeVisible();if(completed)await expect(page.getByRole("status")).toContainText("หลักฐานการตัดสินใจจำลองถูกเก็บ");}
test.beforeAll(async({browser})=>{const context=await browser.newContext({baseURL:origin,extraHTTPHeaders:{"x-real-ip":"synthetic-p2-fixture-"+randomUUID()}}),page=await context.newPage();await login(page,"synthetic.admin");const registry=await context.request.get("/api/p2/doctors").then(r=>r.json());unitId=registry.units[0].id;const key="SYNTHETIC-E2E-"+suffix();const r=await post(context,"/api/p2/doctors",{action:"propose",doctorKey:key,name:"SYNTHETIC Doctor Browser",unitId,effectiveFrom:"2026-01-01T00:00:00.000Z",authorization:"SYNTHETIC isolated browser fixture",vector:{width:600,height:200,strokes:[[[20,20],[80,80],[150,40]]]}});expect(r.ok()).toBe(true);doctorId=(await r.json()).id;await page.getByRole("button",{name:"ออกจากระบบ",exact:true}).click();await expect(page).toHaveURL(/\/login$/);await login(page,"synthetic.approver");expect((await post(context,"/api/p2/doctors",{action:"approve",id:doctorId,reason:"จำลอง: fixture approval"})).ok()).toBe(true);await context.close();});

test("registration waits for delayed units and requires an explicit unit before POST",async({page})=>{
 await login(page);
 let release!:()=>void,responseReady!:()=>void,registrationPosts=0;
 const released=new Promise<void>(resolve=>{release=resolve;}),ready=new Promise<void>(resolve=>{responseReady=resolve;});
 page.on("request",request=>{if(request.method()==="POST"&&new URL(request.url()).pathname==="/api/p2/register")registrationPosts++;});
 await page.route("**/api/p2/cases?*",async route=>{const response=await route.fetch();expect(response.ok()).toBe(true);responseReady();await released;await route.fulfill({response});});
 try{
  await page.goto("/cases");await ready;
  await page.getByRole("button",{name:"ลงทะเบียน ANC",exact:true}).click();
  const n=suffix(),ln="00990"+n,hn="00990"+n;
  await page.getByLabel("LN HIS จำลอง",{exact:false}).fill(ln);await page.getByLabel("HN จำลอง",{exact:false}).fill(hn);
  const unit=page.getByLabel("หน่วยงานลงทะเบียน",{exact:false});
  await expect(unit).toHaveValue("");await expect(unit.locator("option")).toHaveCount(1);
  expect(await unit.evaluate(element=>(element as HTMLSelectElement).validity.valueMissing)).toBe(true);
  await page.getByRole("button",{name:"ตรวจและลงทะเบียน",exact:true}).click();
  await expect(unit).toBeFocused();await expect(page.getByRole("dialog")).toBeVisible();expect(registrationPosts).toBe(0);
  release();
  await expect(unit.locator(`option[value="${unitId}"]`)).toHaveCount(1);await expect(unit).toHaveValue("");
  await unit.selectOption(unitId);await expect(unit).toHaveValue(unitId);
  const registered=page.waitForResponse(response=>response.request().method()==="POST"&&new URL(response.url()).pathname==="/api/p2/register");
  await page.getByRole("button",{name:"ตรวจและลงทะเบียน",exact:true}).click();
  const response=await registered;expect(response.ok()).toBe(true);expect(response.request().postDataJSON().unitId).toBe(unitId);expect(registrationPosts).toBe(1);
  const {caseId}=await response.json();await expect(page).toHaveURL(new RegExp(`/cases/${caseId}$`));await expect(page.getByRole("heading",{name:/เคสจำลอง LN/})).toBeVisible();
 }finally{release();await page.unroute("**/api/p2/cases?*");}
});

